{"sql": "-- Helper function to check if a user is a channel owner
CREATE OR REPLACE FUNCTION public.is_channel_owner(channel_id UUID, user_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.channels 
        WHERE id = channel_id AND owner_id = user_id
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Helper function to check if a user is a channel moderator
CREATE OR REPLACE FUNCTION public.is_channel_moderator(channel_id UUID, user_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.channel_moderators 
        WHERE channel_id = is_channel_moderator.channel_id AND user_id = is_channel_moderator.user_id
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Helper function to check if a user can moderate a channel (owner OR moderator)
CREATE OR REPLACE FUNCTION public.can_moderate_channel(channel_id UUID, user_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN public.is_channel_owner(channel_id, user_id) OR public.is_channel_moderator(channel_id, user_id);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Helper function to get current user ID from session
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS UUID AS $$
BEGIN
    RETURN current_setting('app.current_user_id', true)::UUID;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE;"}

