{"sql": "-- Enable Row Level Security on all tables
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;"}

{"sql": "-- Channel Moderators Table Policies
-- SELECT: Users can see moderator lists for channels
CREATE POLICY channel_moderators_select_policy ON public.channel_moderators
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM public.channels c
            WHERE c.id = channel_moderators.channel_id 
            AND (c.is_public = true OR public.current_user_id() IS NOT NULL)
        )
    );

-- INSERT: Only channel owners can add moderators
CREATE POLICY channel_moderators_insert_policy ON public.channel_moderators
    FOR INSERT
    WITH CHECK (
        public.is_channel_owner(channel_id, public.current_user_id())
    );

-- DELETE: Channel owners can remove moderators; moderators can remove themselves
CREATE POLICY channel_moderators_delete_policy ON public.channel_moderators
    FOR DELETE
    USING (
        public.is_channel_owner(channel_id, public.current_user_id())
        OR user_id = public.current_user_id()
    );

-- No UPDATE policy needed as this is a junction table with no updateable columns beyond the key"}

{"sql": "-- Additional indexes to optimize RLS policy performance
-- (Many already exist from the schema examination)

-- Composite index for posts channel and author (if not exists)
CREATE INDEX IF NOT EXISTS idx_posts_channel_author ON public.posts (channel_id, author_id);

-- Composite index for comments post and author (if not exists)  
CREATE INDEX IF NOT EXISTS idx_comments_post_author ON public.comments (post_id, author_id);

-- Index for quick channel access checks
CREATE INDEX IF NOT EXISTS idx_channels_public_owner ON public.channels (is_public, owner_id);

-- Index for user public profile lookups
CREATE INDEX IF NOT EXISTS idx_users_public_id ON public.users (is_public, id);"}

{"sql": "-- Grant execute permissions on helper functions to public role
-- This allows RLS policies to use these functions
GRANT EXECUTE ON FUNCTION public.is_channel_owner(UUID, UUID) TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_channel_moderator(UUID, UUID) TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_moderate_channel(UUID, UUID) TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.current_user_id() TO PUBLIC;"}

{"sql": "-- Test 1: Verify helper functions work correctly
SELECT 
    'is_channel_owner test' as test_name,
    public.is_channel_owner('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '11111111-1111-1111-1111-111111111111') as alice_owns_public_channel,
    public.is_channel_owner('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '22222222-2222-2222-2222-222222222222') as bob_owns_private_channel,
    public.is_channel_owner('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '22222222-2222-2222-2222-222222222222') as bob_owns_alice_channel;

SELECT 
    'is_channel_moderator test' as test_name,
    public.is_channel_moderator('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '33333333-3333-3333-3333-333333333333') as carol_moderates_public,
    public.is_channel_moderator('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '33333333-3333-3333-3333-333333333333') as carol_moderates_private;

SELECT 
    'can_moderate_channel test' as test_name,
    public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '11111111-1111-1111-1111-111111111111') as alice_can_moderate_her_channel,
    public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '33333333-3333-3333-3333-333333333333') as carol_can_moderate_as_mod,
    public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '44444444-4444-4444-4444-444444444444') as david_cannot_moderate;"}

{"sql": "-- Test 2: Test user access as Alice (public profile, channel owner)
SET app.current_user_id = '11111111-1111-1111-1111-111111111111';

-- Alice should see public users and herself
SELECT 'Alice can see users' as test, username, is_public 
FROM public.users 
ORDER BY username;

-- Alice should see all public channels
SELECT 'Alice can see channels' as test, name, is_public, owner_id = public.current_user_id() as is_owner
FROM public.channels 
ORDER BY name;"}

{"sql": "-- Test 5: Test unauthorized access as David (no special permissions)
SET app.current_user_id = '44444444-4444-4444-4444-444444444444';

-- David should only see public users
SELECT 'David can see users' as test, username, is_public 
FROM public.users 
WHERE is_public = true OR id = public.current_user_id()
ORDER BY username;

-- Test if David can moderate anything (should be false)
SELECT 'David moderation test' as test,
       public.can_moderate_channel('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', public.current_user_id()) as can_moderate_public,
       public.can_moderate_channel('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', public.current_user_id()) as can_moderate_private;"}

